function uniqueValues(values: readonly string[]): string[] {
  return Array.from(new Set(values.map(value => String(value).trim()).filter(Boolean)))
}

function fieldParseSections(field: TrackerRunBattleReportField): readonly TrackerRunBattleReportSection[] {
  return field.parseSections ?? [field.section]
}

function fieldParseLabels(field: TrackerRunBattleReportField): string[] {
  const labelAliases = 'labelAliases' in field ? (field.labelAliases ?? []) : []
  return uniqueValues([field.label, ...labelAliases, ...((LOCALIZED_FIELD_ALIASES as Partial<Record<string, readonly string[]>>)[field.key] ?? [])])
}

function fieldAliasLabels(field: TrackerRunBattleReportField): string[] {
  const labelAliases = 'labelAliases' in field ? (field.labelAliases ?? []) : []
  const inputAliases = 'inputAliases' in field ? (field.inputAliases ?? []) : []
  return uniqueValues([field.label, ...labelAliases, ...inputAliases])
}

const TRACK_RUN_ALIAS_GROUP_LABEL_USAGE = (() => {
  const usage = new Map<string, Set<string>>()

  for (const field of TRACK_RUN_BATTLE_REPORT_FIELDS) {
    if ('includeInAliasGroups' in field && field.includeInAliasGroups === false) continue
    for (const alias of fieldAliasLabels(field)) {
      const normalized = alias.toLowerCase()
      const keys = usage.get(normalized) ?? new Set<string>()
      keys.add(field.key)
      usage.set(normalized, keys)
    }
  }

  return new Map(Array.from(usage.entries(), ([alias, keys]) => [alias, keys.size]))
})()

function fieldOutputAliasLabels(field: TrackerRunBattleReportField): string[] {
  return fieldAliasLabels(field).filter(alias => (TRACK_RUN_ALIAS_GROUP_LABEL_USAGE.get(alias.toLowerCase()) ?? 0) === 1)
}

export const TRACK_RUN_CANONICAL_REPORT_LABEL_BY_KEY = Object.freeze(
  Object.fromEntries(TRACK_RUN_BATTLE_REPORT_FIELDS.map(field => [field.key, field.label])) as Record<string, string>,
)

export const TRACK_RUN_BATTLE_REPORT_PARSE_LABELS_BY_KEY = Object.freeze(
  Object.fromEntries(TRACK_RUN_BATTLE_REPORT_FIELDS.map(field => [field.key, fieldParseLabels(field)])) as Record<string, string[]>,
)

export const TRACK_RUN_BATTLE_REPORT_LABEL_TO_KEY = Object.freeze(
  Object.fromEntries(TRACK_RUN_BATTLE_REPORT_FIELDS.map(field => [field.label, field.key])) as Record<string, string>,
)

export const TRACK_RUN_INLINE_BATTLE_REPORT_SECTION_LABELS = Object.freeze(
  Object.fromEntries(
    TRACK_RUN_BATTLE_REPORT_SECTION_HEADERS.map(section => [
      section,
      uniqueValues(
        TRACK_RUN_BATTLE_REPORT_FIELDS
          .filter(field => fieldParseSections(field).includes(section))
          .flatMap(field => fieldParseLabels(field)),
      ),
    ]),
  ) as Record<TrackerRunBattleReportSection, string[]>,
)

export const TRACK_RUN_CANONICAL_KEY_ORDER: readonly string[] = TRACK_RUN_BATTLE_REPORT_FIELDS
  .filter(field => !('includeInAliasGroups' in field) || field.includeInAliasGroups !== false)
  .map(field => field.key)

export const TRACK_RUN_OUTPUT_ALIAS_GROUPS: readonly RunDataAliasGroup[] = TRACK_RUN_BATTLE_REPORT_FIELDS
  .filter(field => !('includeInAliasGroups' in field) || field.includeInAliasGroups !== false)
  .map(field => ({
    key: field.key,
    aliases: fieldOutputAliasLabels(field),
  }))

export const TRACK_RUN_SUBMIT_ALIAS_GROUPS: readonly RunDataAliasGroup[] = TRACK_RUN_OUTPUT_ALIAS_GROUPS

export const TRACK_RUN_INLINE_BATTLE_REPORT_LABELS: readonly string[] = uniqueValues(
  TRACK_RUN_BATTLE_REPORT_FIELDS.flatMap(field => fieldParseLabels(field)),
)
